func tick(delta: float) -> void:
	if _finished or _pointer == null or not is_instance_valid(_pointer):
		return
	_pointer_phase += maxf(delta, 0.0)
	_pointer.position = _pointer_base + Vector2(0.0,
		sin(_pointer_phase * 4.0) * 7.0)


func probe_tap(logical_position: Vector2) -> void:

func _process(delta: float) -> void:
	if _done or _root == null:
		return
	_elapsed += delta
	var reveal: float = smoothstep(0.0, 1.0, clampf(_elapsed / 0.16, 0.0, 1.0))
	var exit_alpha := 1.0
	if _elapsed >= EXIT_START:
		exit_alpha = 1.0 - smoothstep(0.0, 1.0,
			clampf((_elapsed - EXIT_START) / (TOTAL_TIME - EXIT_START), 0.0, 1.0))
	_root.modulate.a = minf(reveal, exit_alpha)
	if _name_card != null:
		var name_progress: float = smoothstep(0.0, 1.0,
			clampf((_elapsed - 0.22) / 0.42, 0.0, 1.0))
		_name_card.modulate.a = name_progress
		_name_card.scale = Vector2.ONE * lerpf(0.92, 1.0, name_progress)
	if _boss_anchor != null:
		_animate_boss()
	var flashing: bool = teach_counter and _elapsed >= FLASH_START and _elapsed < EXIT_START
	var pulse: float = 0.5 + 0.5 * sin((_elapsed - FLASH_START) * 8.0)
	if flashing and not _vulnerable_started:
		_vulnerable_started = true
		_play_role("vulnerable")
	if _badge != null:
		_badge.visible = flashing and _badge.texture != null
		_badge.modulate = Color(1.0, 0.94, 0.52, 0.76 + pulse * 0.24)
		_badge.scale = _badge_scale() * (1.10 + pulse * 0.18)
	if _badge_halo != null:
		_badge_halo.visible = flashing
		_badge_halo.scale = Vector2.ONE * (0.88 + pulse * 0.18)
	if _hand != null:
		_hand.visible = flashing
		_hand.position.y = -390.0 + pulse * 28.0
	if _elapsed >= TOTAL_TIME:
		_complete()


func _animate_boss() -> void:

func tick(delta: float) -> void:
	if m == null or m.game != "chapter2_lawn" or not m.g.has(KEY):
		return
	if _input_context_lost():
		return
	_fit()
	var state := _state()
	state["elapsed"] = float(state["elapsed"]) + delta
	state["beat_elapsed"] = float(state["beat_elapsed"]) + delta
	state["mode_elapsed"] = float(state["mode_elapsed"]) + delta
	if String(state["mode"]).begins_with("ignition_"):
		_tick_ignition(delta)
	if m.chapter2_lawn_beat == 4:
		_tick_battle(delta)
	pointer.visible = not String(state["mode"]).begins_with("ignition_")
	var hint := IGNITION_POINT if m.chapter2_lawn_beat == 0 else CONTINUE_RECT.get_center()
	if m.chapter2_lawn_beat == 4:
		var current := battle.engine()
		if current.state == BossEncounter2D.State.OPENING:
			hint = KING_RECT.get_center()
		else:
			hint = _screen(current.patterns.readout().get("safe_point", Vector2.ZERO) as Vector2)
	pointer.position = hint + Vector2(18.0, 8.0 + sin(float(state["elapsed"]) * 3.0) * 9.0)
	queue_redraw()
	if foreground != null:
		foreground.queue_redraw()

func _tick_battle(delta: float) -> void:

func _draw() -> void:
	if anchor == Vector2.ZERO:
		return
	var pressing: bool = _pressing()
	var halo: float = 30.0 if pressing else 20.0
	draw_circle(anchor, halo, Color(cue_color, 0.28))
	if hand_texture != null:
		var hand_size := Vector2(82.0, 82.0)
		var hand_origin: Vector2 = anchor - hand_size * Vector2(0.435, 0.875)
		hand_origin.y -= 0.0 if pressing else 10.0
		draw_texture_rect(hand_texture, Rect2(hand_origin, hand_size), false)
	else:
		draw_circle(anchor, 13.0, Color(1.0, 0.98, 0.88, 0.95))
	if pressing:
		var ring: float = 18.0 + fmod(t * 46.0, 26.0)
		draw_arc(anchor, ring, 0.0, TAU, 32, Color(cue_color, 0.7), 3.0, true)
	if mode == "hold" and pressing:
		var full_t: float = float(HitEngine.CHARGE_STAGE_T[2])
		var cycle: float = fmod(t, full_t + 1.1)
		var grow: float = clampf((cycle - 0.7) / full_t, 0.0, 1.0)
		var stage_col: Color = HitEngine.CHARGE_COLORS[clampi(int(grow * 3.0), 0, 2)]
		draw_arc(anchor, 34.0 + grow * 26.0, -PI * 0.5,
			-PI * 0.5 + TAU * maxf(grow, 0.06), 40,
			Color(stage_col.r, stage_col.g, stage_col.b, 0.85), 5.0, true)
	var chip: Texture2D = hold_chip if mode == "hold" else tap_chip
	if show_chip and chip != null and mode != "":
		var chip_size := Vector2(82.0, 82.0)
		draw_texture_rect(chip, Rect2(anchor + Vector2(54.0, -105.0), chip_size), false)

func _ready() -> void:
	mouse_filter = Control.MOUSE_FILTER_IGNORE
	set_anchors_and_offsets_preset(Control.PRESET_FULL_RECT)
	if ResourceLoader.exists(HAND_PATH):
		hand_texture = load(HAND_PATH) as Texture2D
	if ResourceLoader.exists(TAP_CHIP_PATH):
		tap_chip = load(TAP_CHIP_PATH) as Texture2D
	if ResourceLoader.exists(HOLD_CHIP_PATH):
		hold_chip = load(HOLD_CHIP_PATH) as Texture2D

