func _begin_live_drag(position: Vector2) -> void:
	_dragging = true
	_last_input_time = _demo_time
	if _demo_pointer != null and is_instance_valid(_demo_pointer):
		_demo_pointer.visible = false
	_update_live_drag(position)


func _update_live_drag(position: Vector2) -> void:

func _collect_item(index: int) -> void:
	if index < 0 or index >= TRASH_COUNT:
		return
	var bit: int = 1 << index
	if (_progress_mask & bit) != 0:
		return
	_progress_mask |= bit
	progress_changed.emit(_progress_mask)
	_spawn_catch_feedback(TRASH_POSITIONS[index])
	if index < _trash_sprites.size():
		var piece: Sprite2D = _trash_sprites[index]
		if piece != null and is_instance_valid(piece):
			piece.set_meta("in_flight", true)
			piece.z_index = 176
			var flight: Tween = piece.create_tween().set_parallel(true)
			_flight_tweens.append(flight)
			flight.tween_property(piece, "position", BASKET_POSITION, 0.48) \
				.set_trans(Tween.TRANS_BACK).set_ease(Tween.EASE_IN)
			flight.tween_property(piece, "scale", piece.scale * 0.42, 0.48)
			flight.tween_property(piece, "modulate:a", 0.0, 0.12).set_delay(0.39)
			flight.chain().tween_callback(_finish_piece_flight.bind(index, flight))
	if _progress_mask == ALL_MASK:
		_completed = true
		_dragging = false
		if _demo_pointer != null and is_instance_valid(_demo_pointer):
			_demo_pointer.visible = false
		_emit_completed_once()
	queue_redraw()


func _emit_completed_once() -> void:

func start() -> void:
	_running = true
	mouse_filter = Control.MOUSE_FILTER_STOP
	_demo_time = 0.0
	_dragging = false
	if not _completed:
		_claim_room_actor()
	if _demo_pointer != null and is_instance_valid(_demo_pointer):
		_demo_pointer.visible = not _completed
	if _completed:
		_emit_completed_once()
	set_process(true)
	queue_redraw()


func stop() -> void:

func _free_owned_nodes() -> void:
	for sprite: Sprite2D in _slice_nodes:
		if sprite != null and is_instance_valid(sprite):
			sprite.queue_free()
	_slice_nodes.clear()
	_slice_base_scales.clear()
	if _scrubber != null and is_instance_valid(_scrubber):
		_scrubber.queue_free()
	_scrubber = null
	if _wash_overlay != null and is_instance_valid(_wash_overlay):
		_wash_overlay.queue_free()
	_wash_overlay = null
	if _guide_hand != null and is_instance_valid(_guide_hand):
		_guide_hand.queue_free()
	_guide_hand = null


func _show_scrubber(point: Vector2) -> void:

func _update_guide_hand() -> void:
	if _guide_hand == null or not is_instance_valid(_guide_hand):
		return
	var working := _contact_action != null and _contact_action.active
	var lane := _hint_lane if _hint_lane >= 0 else _first_uncleared_lane()
	var cycle := GUIDE_STROKE_SECONDS + GUIDE_REST_SECONDS
	var phase := fmod(maxf(_idle_time - GUIDE_IDLE_SECONDS, 0.0), cycle)
	var demonstrating := _active and not _touch_active and not working and lane >= 0 \
		and _idle_time >= GUIDE_IDLE_SECONDS and phase <= GUIDE_STROKE_SECONDS
	_guide_hand.visible = demonstrating
	if not demonstrating:
		return
	# Demonstrate the real verb: one downward stroke down the next lane.
	var t := clampf(phase / GUIDE_STROKE_SECONDS, 0.0, 1.0)
	var eased := t * t * (3.0 - 2.0 * t)
	var rect := _lane_rect(lane)
	var fingertip := Vector2(rect.get_center().x,
		lerpf(rect.position.y + rect.size.y * 0.12, rect.position.y + rect.size.y * 0.80, eased))
	_guide_hand.position = fingertip - GUIDE_FINGERTIP * _guide_hand.scale
	_guide_hand.modulate.a = clampf(minf(t, 1.0 - t) * 6.0, 0.0, 1.0)


